def chart_data_js(data_dict, x_label='x', y_label='y'):
    """Convert Python dict to Chart.js data format."""
    labels = json.dumps(list(data_dict.keys()))
    values = json.dumps(list(data_dict.values()))
    return labels, values

def chart_data_xy(x_list, y_list):
    return json.dumps(list(x_list)), json.dumps(list(y_list))

def kpi_card(label, value, unit="", highlight=False):
    cls = "kpi-highlight" if highlight else ""
    return f'''<div class="kpi-card {cls}">
