def fmt(n, decimals=1):
    """Format number with comma separators."""
    if isinstance(n, float):
        return f"{n:,.{decimals}f}"
    return str(n)

def pct(n, decimals=1):
    return f"{n*100:.{decimals}f}%"

# ── KPI Calculations ─────────────────────────────────────────────────────
kpi_avg_wait = df['waiting_time'].mean()
kpi_avg_energy = df['energy_consumed_kWh'].mean()
