kpi_renew_ratio = df['renewable_energy_ratio'].mean()
kpi_opt_reward = df['optimization_reward'].mean()

# KPI by segments
wait_by_loc = df.groupby('location_type')['waiting_time'].mean().round(1).to_dict()
wait_by_slot = df.groupby('time_slot')['waiting_time'].mean().round(1).to_dict()
wait_by_loc_slot = df.groupby(['location_type', 'time_slot'])['waiting_time'].mean().round(1)

renew_by_weather = df.groupby('weather_condition')['renewable_energy_ratio'].mean().round(3).to_dict()
renew_by_slot = df.groupby('time_slot')['renewable_energy_ratio'].mean().round(3).to_dict()
renew_by_loc = df.groupby('location_type')['renewable_energy_ratio'].mean().round(3).to_dict()

# ── SECTION 1: Station Utilization & Demand ───────────────────────────────
sec1_demand_by_loc = df.groupby('location_type').agg(
    sessions=('station_id', 'count'),
