    total_energy=('energy_consumed_kWh', 'sum')
).round(1)
sec1_demand_by_loc['sessions_pct'] = sec1_demand_by_loc['sessions'] / n_rows

sec1_demand_by_slot = df.groupby('time_slot')['charging_demand'].agg(['mean', 'sum', 'count']).round(1)
# Order by slot type
slot_order = {'Peak': 0, 'Mid-Peak': 1, 'Off-Peak': 2}
sec1_demand_by_slot = sec1_demand_by_slot.loc[sec1_demand_by_slot.index.sort_values(key=lambda x: [slot_order.get(i, 99) for i in x])]

sec1_top_stations = df.groupby('station_id').agg(
    sessions=('vehicle_id', 'count'),
    avg_demand=('charging_demand', 'mean'),
    avg_load=('station_load', 'mean'),
    avg_wait=('waiting_time', 'mean')
).round(1).sort_values('sessions', ascending=False).head(10)

sec1_demand_by_day = df.groupby('day_of_week')['charging_demand'].mean().round(1)
day_order = {d: i for i, d in enumerate(days)}
sec1_demand_by_day = sec1_demand_by_day.sort_index(key=lambda x: [day_order.get(i, 99) for i in x])

# ── SECTION 2: Queue Length & Waiting Time Analysis ──────────────────────
sec2_wait_by_loc_slot = df.groupby(['location_type', 'time_slot'])['waiting_time'].agg(['mean', 'median', 'max']).round(1)
sec2_queue_by_loc_slot = df.groupby(['location_type', 'time_slot'])['queue_length'].mean().round(1)
sec2_wait_by_vehicle = df.groupby('vehicle_type')['waiting_time'].agg(['mean', 'count']).round(1).sort_values('mean', ascending=False)
sec2_wait_by_traffic = df.groupby('traffic_density')['waiting_time'].agg(['mean', 'median', 'max']).round(1)
sec2_wait_by_weather = df.groupby('weather_condition')['waiting_time'].mean().round(1).sort_values(ascending=False)

# Heatmap data: waiting_time by time_slot vs location_type
heatmap_wait = df.pivot_table(values='waiting_time', index='time_slot', columns='location_type', aggfunc='mean').round(1)
# Reorder time_slot index
heatmap_wait = heatmap_wait.reindex(['Peak', 'Mid-Peak', 'Off-Peak'])

# Queue length heatmap
heatmap_queue = df.pivot_table(values='queue_length', index='time_slot', columns='location_type', aggfunc='mean').round(1)
heatmap_queue = heatmap_queue.reindex(['Peak', 'Mid-Peak', 'Off-Peak'])

# ── SECTION 3: Energy Consumption & Grid Load Patterns ───────────────────
sec3_energy_by_loc = df.groupby('location_type')['energy_consumed_kWh'].agg(['mean', 'sum', 'std']).round(1)
