# ── SECTION 4: Renewable Energy & Pricing ────────────────────────────────
sec4_renew_by_weather = df.groupby('weather_condition')['renewable_energy_ratio'].mean().round(3).sort_values(ascending=False)
sec4_renew_by_slot = df.groupby('time_slot')['renewable_energy_ratio'].mean().round(3)
