sec4_price_by_slot = df.groupby('time_slot')['electricity_price'].mean().round(2)
sec4_price_by_slot = sec4_price_by_slot.loc[sec4_price_by_slot.index.sort_values(key=lambda x: [slot_order.get(i, 99) for i in x])]
sec4_price_by_weather = df.groupby('weather_condition')['electricity_price'].mean().round(2).sort_values(ascending=False)

# Correlation between renewable_energy_ratio and electricity_price
sec4_corr_renew_price = df['renewable_energy_ratio'].corr(df['electricity_price'])

