def chart_data_js(data_dict, x_label='x', y_label='y'):
    """Convert Python dict to Chart.js data format."""
    labels = json.dumps(list(data_dict.keys()))
    values = json.dumps(list(data_dict.values()))
    return labels, values

def chart_data_xy(x_list, y_list):
    return json.dumps(list(x_list)), json.dumps(list(y_list))

def kpi_card(label, value, unit="", highlight=False):
    cls = "kpi-highlight" if highlight else ""
    return f'''<div class="kpi-card {cls}">
        <div class="kpi-label">{label}</div>
        <div class="kpi-value">{fmt(value)}{unit}</div>
    </div>'''

def chart_container(canvas_id, height="300"):
    return f'<div class="chart-wrap"><canvas id="{canvas_id}" height="{height}"></canvas></div>'

def generate_chart_js(chart_id, chart_type, labels_js, datasets_js, options_js=None):
    """Generate Chart.js initialization code."""
    opts = options_js if options_js else "{}"
    return f'''new Chart(document.getElementById('{chart_id}'), {{
        type: '{chart_type}',
        data: {{ labels: {labels_js}, datasets: {datasets_js} }},
        options: {opts}
