.report-header h1 {{
    font-size: 28px;
    font-weight: 800;
    letter-spacing: -0.5px;
    margin-bottom: 6px;
}}
.report-header .subtitle {{
    font-size: 15px;
    color: var(--teal-light);
    margin-bottom: 4px;
}}
.report-header .meta {{
    font-size: 12px;
    color: var(--gray-500);
}}

/* ── KPI Banner ── */
.kpi-banner {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 16px;
    margin-bottom: 32px;
}}
.kpi-card {{
    background: white;
    padding: 20px 24px;
    border-radius: 10px;
    box-shadow: 0 1px 4px rgba(0,0,0,0.06);
    border-left: 4px solid var(--teal);
}}
.kpi-card.kpi-highlight {{ border-left-color: var(--amber); }}
.kpi-label {{ font-size: 11px; text-transform: uppercase; color: var(--gray-500); letter-spacing: 0.5px; margin-bottom: 4px; }}
.kpi-value {{ font-size: 28px; font-weight: 800; color: var(--gray-900); }}

/* ── Sections ── */
.section {{
    background: white;
    border-radius: 10px;
    box-shadow: 0 1px 4px rgba(0,0,0,0.06);
    padding: 32px;
    margin-bottom: 24px;
}}
.section h2 {{
    font-size: 22px;
    font-weight: 700;
    color: var(--navy);
    margin-bottom: 6px;
    padding-bottom: 12px;
    border-bottom: 2px solid var(--gray-100);
}}
.section h3 {{
    font-size: 16px;
    font-weight: 600;
    color: var(--gray-700);
    margin: 24px 0 12px;
}}
.section p {{
    font-size: 14px;
    color: var(--gray-700);
    margin-bottom: 12px;
}}
.section .objective {{
    font-size: 13px;
    color: var(--gray-500);
    font-style: italic;
    margin-bottom: 20px;
}}

/* ── Charts ── */
.chart-wrap {{
    margin: 16px 0;
    position: relative;
}}
.chart-row {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
}}
@media (max-width: 768px) {{ .chart-row {{ grid-template-columns: 1fr; }} }}

/* ── Tables ── */
.data-table {{
    width: 100%;
    border-collapse: collapse;
    margin: 12px 0 20px;
    font-size: 13px;
}}
.data-table th {{
    background: var(--gray-50);
    padding: 10px 12px;
    text-align: left;
    font-weight: 600;
    color: var(--gray-700);
    border-bottom: 2px solid var(--gray-200);
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 0.3px;
}}
.data-table td {{
    padding: 8px 12px;
    border-bottom: 1px solid var(--gray-100);
    color: var(--gray-700);
}}
.data-table tr:hover td {{ background: var(--gray-50); }}

/* ── Insights ── */
.insight-box {{
    background: linear-gradient(135deg, #f0fdf9 0%, #e8faf7 100%);
    border-left: 4px solid var(--teal);
    padding: 16px 20px;
    border-radius: 6px;
    margin: 16px 0;
}}
.insight-box h4 {{
    font-size: 13px;
    color: var(--teal);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 6px;
}}
.insight-box p {{ font-size: 13px; color: var(--gray-700); margin: 0; }}

.insight-warn {{
    background: linear-gradient(135deg, #fff8f0 0%, #fff3e6 100%);
    border-left-color: var(--amber);
}}
.insight-warn h4 {{ color: var(--amber); }}

.insight-crit {{
    background: linear-gradient(135deg, #fff5f5 0%, #ffe8e8 100%);
    border-left-color: var(--red);
}}
.insight-crit h4 {{ color: var(--red); }}

/* ── Recommendation Cards ── */
.rec-cards {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(340px, 1fr));
    gap: 16px;
    margin: 20px 0;
}}
.rec-card {{
    border: 1px solid var(--gray-200);
    border-radius: 8px;
    padding: 20px;
    background: white;
}}
.rec-card h4 {{
    font-size: 14px;
    font-weight: 700;
    color: var(--navy);
    margin-bottom: 8px;
}}
.rec-card .rec-tag {{
    display: inline-block;
    font-size: 10px;
    font-weight: 700;
    padding: 3px 8px;
    border-radius: 3px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 10px;
}}
.rec-tag.high {{ background: #fee2e2; color: #991b1b; }}
.rec-tag.medium {{ background: #fef3c7; color: #92400e; }}
.rec-tag.low {{ background: #dcfce7; color: #166534; }}
.rec-card p {{ font-size: 13px; color: var(--gray-700); margin: 0; }}
.rec-card .rec-metric {{
    margin-top: 12px;
    padding: 8px 12px;
    background: var(--gray-50);
    border-radius: 4px;
    font-size: 12px;
    color: var(--gray-500);
}}

/* ── Footer ── */
.footer {{
    text-align: center;
    color: var(--gray-500);
    font-size: 12px;
    padding: 20px;
    margin-top: 20px;
}}
</style>
</head>
<body>

<!-- Navigation -->
<nav class="nav">
    <span class="nav-title">&#9889; EV Charging Analytics</span>
    <div class="nav-links">
        <a href="#top">Overview</a>
        <a href="#sec-utilization">Station Utilization</a>
        <a href="#sec-queue">Queue & Wait</a>
        <a href="#sec-energy">Energy & Grid</a>
        <a href="#sec-renewable">Renewables & Pricing</a>
        <a href="#sec-vehicle">Vehicle Profiles</a>
        <a href="#sec-recommendations">Recommendations</a>
    </div>
</nav>

<div class="container" id="top">

<!-- Report Header -->
<div class="report-header">
    <h1>EV Charging Network Performance &amp; Grid Optimization</h1>
    <p class="subtitle">Comprehensive Analytics Report for Infrastructure Managers &amp; Grid Planners</p>
    <p class="meta">Dataset: {n_rows:,} sessions across {n_stations} stations | {n_vehicles:,} vehicles | Generated: {gen_time}</p>
</div>

<!-- KPI Summary Banner -->
<div class="kpi-banner">
    {kpi_card('Avg Waiting Time', kpi_avg_wait, ' min', kpi_avg_wait > 10)}
    {kpi_card('Avg Energy / Session', kpi_avg_energy, ' kWh')}
    {kpi_card('Mean Station Load', kpi_mean_load, ' kW')}
    {kpi_card('Renewable Energy Ratio', kpi_renew_ratio * 100, '%', kpi_renew_ratio < 0.3)}
    {kpi_card('Mean Optimization Reward', kpi_opt_reward, '', kpi_opt_reward < 0)}
</div>

<!-- ═══════════════════════════════════════════════════════════════════ -->
<!-- SECTION 1: Station Utilization & Demand -->
<!-- ═══════════════════════════════════════════════════════════════════ -->
<div class="section" id="sec-utilization">
<h2>1. Station Utilization &amp; Demand Analysis</h2>
<p class="objective">Analyzing charging demand distribution across stations and location types, identifying high-demand stations, peak utilization periods, and capacity constraints.</p>

<div class="chart-row">
    {chart_container('chart-demand-loc')}
    {chart_container('chart-demand-slot')}
</div>

<h3>Sessions & Demand by Location Type</h3>
<table class="data-table">
<tr><th>Location</th><th>Sessions</th><th>Share</th><th>Avg Demand</th><th>Total Energy (kWh)</th></tr>'''

for loc in ['Urban', 'Highway', 'Suburban']:
    if loc in sec1_demand_by_loc.index:
        r = sec1_demand_by_loc.loc[loc]
        html += f'<tr><td><strong>{loc}</strong></td><td>{fmt(r["sessions"], 0)}</td><td>{pct(r["sessions_pct"])}</td><td>{fmt(r["avg_demand"])}</td><td>{fmt(r["total_energy"], 0)}</td></tr>'

html += '''</table>

<div class="insight-box">
    <h4>Key Finding</h4>
    <p>'''

top_loc = sec1_demand_by_loc['avg_demand'].idxmax()
top_loc_val = sec1_demand_by_loc.loc[top_loc, 'avg_demand']
html += f'<strong>{top_loc}</strong> stations experience the highest average charging demand ({fmt(top_loc_val)}), indicating where capacity expansion should be prioritized. '

peak_demand = sec1_demand_by_slot.loc['Peak', 'mean']
offpeak_demand = sec1_demand_by_slot.loc['Off-Peak', 'mean']
html += f'Peak-period demand ({fmt(peak_demand)}) is <strong>{fmt(peak_demand / offpeak_demand, 2)}&times;</strong> Off-Peak levels ({fmt(offpeak_demand)}), creating a substantial load imbalance across the day.</p>'
html += '''</div>

<h3>Top 10 Stations by Session Volume</h3>
<table class="data-table">
<tr><th>Station</th><th>Sessions</th><th>Avg Demand</th><th>Avg Load (kW)</th><th>Avg Wait (min)</th></tr>'''

for st, r in sec1_top_stations.iterrows():
    html += f'<tr><td><strong>{st}</strong></td><td>{fmt(r["sessions"], 0)}</td><td>{fmt(r["avg_demand"])}</td><td>{fmt(r["avg_load"])}</td><td>{fmt(r["avg_wait"])}</td></tr>'

html += '''</table>

<h3>Demand Profile by Day of Week</h3>'''
html += chart_container('chart-demand-day')

html += '''
<div class="insight-box insight-warn">
    <h4>Capacity Constraint Alert</h4>
    <p>'''

top_station = sec1_top_stations.index[0]
top_station_load = sec1_top_stations.loc[top_station, 'avg_load']
top_station_wait = sec1_top_stations.loc[top_station, 'avg_wait']
html += f'Station <strong>{top_station}</strong> handles the highest session volume with average load of <strong>{fmt(top_station_load)} kW</strong> and wait times of <strong>{fmt(top_station_wait)} min</strong>. Consider adding charger units or redirecting overflow to nearby stations during peak windows.</p>'
html += '''</div>
</div>

<!-- ═══════════════════════════════════════════════════════════════════ -->
<!-- SECTION 2: Queue & Waiting Time -->
<!-- ═══════════════════════════════════════════════════════════════════ -->
<div class="section" id="sec-queue">
<h2>2. Queue Length &amp; Waiting Time Analysis</h2>
<p class="objective">Examining queue lengths and waiting times by station, time slot, vehicle type, and traffic density to identify bottleneck patterns and quantify the customer experience impact.</p>

<div class="chart-row">
    {chart_container('chart-wait-heatmap')}
    {chart_container('chart-wait-vehicle')}
</div>

<h3>Wait Time Heatmap: Location Type &times; Time Slot</h3>
<table class="data-table">
<tr><th>Location</th><th>Peak</th><th>Mid-Peak</th><th>Off-Peak</th><th>Overall Avg</th></tr>'''

for loc in ['Urban', 'Highway', 'Suburban']:
    if loc in heatmap_wait.columns:
        peak_val = heatmap_wait.loc['Peak', loc] if 'Peak' in heatmap_wait.index else '-'
        mid_val = heatmap_wait.loc['Mid-Peak', loc] if 'Mid-Peak' in heatmap_wait.index else '-'
        off_val = heatmap_wait.loc['Off-Peak', loc] if 'Off-Peak' in heatmap_wait.index else '-'
        overall = df[df['location_type'] == loc]['waiting_time'].mean()
        html += f'<tr><td><strong>{loc}</strong></td><td>{fmt(peak_val)} min</td><td>{fmt(mid_val)} min</td><td>{fmt(off_val)} min</td><td><strong>{fmt(overall)} min</strong></td></tr>'

html += '''</table>

<h3>Average Queue Length Heatmap: Location Type &times; Time Slot</h3>
<table class="data-table">
<tr><th>Location</th><th>Peak</th><th>Mid-Peak</th><th>Off-Peak</th></tr>'''

for loc in ['Urban', 'Highway', 'Suburban']:
    if loc in heatmap_queue.columns:
        peak_q = heatmap_queue.loc['Peak', loc] if 'Peak' in heatmap_queue.index else '-'
        mid_q = heatmap_queue.loc['Mid-Peak', loc] if 'Mid-Peak' in heatmap_queue.index else '-'
        off_q = heatmap_queue.loc['Off-Peak', loc] if 'Off-Peak' in heatmap_queue.index else '-'
        html += f'<tr><td><strong>{loc}</strong></td><td>{fmt(peak_q)} vehicles</td><td>{fmt(mid_q)} vehicles</td><td>{fmt(off_q)} vehicles</td></tr>'

html += '''</table>

<h3>Wait Time by Traffic Density</h3>
<table class="data-table">
<tr><th>Traffic Level</th><th>Mean Wait (min)</th><th>Median Wait (min)</th><th>Max Wait (min)</th></tr>'''

for lvl in ['Low', 'Medium', 'High']:
    if lvl in sec2_wait_by_traffic.index:
        r = sec2_wait_by_traffic.loc[lvl]
        html += f'<tr><td><strong>{lvl}</strong></td><td>{fmt(r["mean"])}</td><td>{fmt(r["median"])}</td><td>{fmt(r["max"])}</td></tr>'

html += '''</table>

<div class="insight-box insight-crit">
    <h4>Critical Customer Experience Finding</h4>
    <p>'''

worst_loc_slot = wait_by_loc_slot.idxmax()
worst_loc_slot_val = wait_by_loc_slot.max()
worst_vehicle = sec2_wait_by_vehicle.index[0]
worst_vehicle_wait = sec2_wait_by_vehicle.iloc[0]['mean']
html += f'Worst-case wait times occur at <strong>{worst_loc_slot[0]} stations during {worst_loc_slot[1]}</strong> ({fmt(worst_loc_slot_val)} min average). <strong>{worst_vehicle}</strong> vehicles experience the longest waits ({fmt(worst_vehicle_wait)} min), likely due to larger battery capacities requiring extended charger availability. Queue lengths follow traffic density patterns tightly, confirming that traffic-driven demand surges are a primary wait-time driver.</p>'
html += '''</div>
</div>

<!-- ═══════════════════════════════════════════════════════════════════ -->
<!-- SECTION 3: Energy Consumption & Grid Load -->
<!-- ═══════════════════════════════════════════════════════════════════ -->
<div class="section" id="sec-energy">
<h2>3. Energy Consumption &amp; Grid Load Patterns</h2>
<p class="objective">Assessing energy consumption patterns, station load profiles across time slots and days of the week, and the relationship between charging power levels and grid stress.</p>

<div class="chart-row">
    {chart_container('chart-load-slot')}
    {chart_container('chart-load-day')}
</div>

<h3>Energy Consumption by Location</h3>
<table class="data-table">
<tr><th>Location</th><th>Avg Energy (kWh)</th><th>Total Energy (kWh)</th><th>Std Dev (kWh)</th></tr>'''

for loc in ['Urban', 'Highway', 'Suburban']:
    if loc in sec3_energy_by_loc.index:
        r = sec3_energy_by_loc.loc[loc]
        html += f'<tr><td><strong>{loc}</strong></td><td>{fmt(r["mean"])}</td><td>{fmt(r["sum"], 0)}</td><td>{fmt(r["std"])}</td></tr>'

html += '''</table>

<h3>Grid Load by Time Slot</h3>
<table class="data-table">
<tr><th>Time Slot</th><th>Mean Load (kW)</th><th>Peak Load (kW)</th></tr>'''

for slot in sec3_load_by_slot.index:
    r = sec3_load_by_slot.loc[slot]
    html += f'<tr><td><strong>{slot}</strong></td><td>{fmt(r["mean"])}</td><td>{fmt(r["max"])}</td></tr>'

html += '''</table>

<div class="chart-row">
    {chart_container('chart-load-loc-slot')}
    {chart_container('chart-power-load')}
</div>

<div class="insight-box">
    <h4>Grid Stress Insight</h4>
    <p>'''

max_load_slot = sec3_load_by_slot['mean'].idxmax()
max_load_val = sec3_load_by_slot['mean'].max()
min_load_slot = sec3_load_by_slot['mean'].idxmin()
min_load_val = sec3_load_by_slot['mean'].min()
html += f'{max_load_slot} periods carry <strong>{fmt(max_load_val)} kW</strong> average load vs. <strong>{fmt(min_load_val)} kW</strong> during {min_load_slot}, a {fmt(max_load_val/min_load_val, 2)}&times; differential. This imbalance strains infrastructure during peak hours while leaving capacity underutilized at other times. Load patterns are consistent across weekdays, suggesting predictable demand that can be managed through scheduled load-shifting programs.</p>'
html += '''</div>
</div>

<!-- ═══════════════════════════════════════════════════════════════════ -->
<!-- SECTION 4: Renewable Energy & Pricing -->
<!-- ═══════════════════════════════════════════════════════════════════ -->
<div class="section" id="sec-renewable">
<h2>4. Renewable Energy Integration &amp; Dynamic Pricing</h2>
<p class="objective">Evaluating the renewable energy ratio across different conditions (time, weather, location) and analyzing how dynamic electricity pricing correlates with demand, renewable availability, and optimization rewards.</p>

<div class="chart-row">
    {chart_container('chart-renew-weather')}
    {chart_container('chart-renew-slot')}
</div>

<h3>Renewable Energy Ratio by Weather Condition</h3>
<table class="data-table">
<tr><th>Weather</th><th>Avg Renewable Ratio</th><th>Price ($/kWh)</th></tr>'''

for w in sec4_renew_by_weather.index:
    r_ratio = sec4_renew_by_weather[w]
    r_price = sec4_price_by_weather.get(w, '-')
    p_str = fmt(r_price, 2) if isinstance(r_price, (int, float)) else str(r_price)
    html += f'<tr><td><strong>{w}</strong></td><td>{pct(r_ratio)}</td><td>${p_str}</td></tr>'

html += '''</table>

<h3>Dynamic Pricing by Time Slot</h3>
<table class="data-table">
<tr><th>Time Slot</th><th>Avg Price ($/kWh)</th><th>Avg Renewable Ratio</th></tr>'''

for slot in sec4_price_by_slot.index:
    price = sec4_price_by_slot[slot]
    renew = sec4_renew_by_slot.get(slot, 0)
    html += f'<tr><td><strong>{slot}</strong></td><td>${fmt(price, 2)}</td><td>{pct(renew)}</td></tr>'

html += f'''</table>

<div class="chart-row">
    {chart_container('chart-price-demand')}
    {chart_container('chart-opt-renew')}
</div>

<div class="insight-box">
    <h4>Pricing &amp; Sustainability Insight</h4>
    <p>Correlation between renewable ratio and electricity price: <strong>r = {fmt(sec4_corr_renew_price, 3)}</strong>. '''

best_renew_weather = sec4_renew_by_weather.index[0]
best_renew_val = sec4_renew_by_weather[best_renew_weather]
best_renew_slot = sec4_renew_by_slot.idxmax()
best_renew_slot_val = sec4_renew_by_slot.max()
html += f'<strong>{best_renew_weather}</strong> weather yields the highest renewable ratio ({pct(best_renew_val)}), and <strong>{best_renew_slot}</strong> periods offer the most green energy ({pct(best_renew_slot_val)}). These conditions present the best opportunity windows for scheduling environmentally-conscious charging. Pricing and renewable availability show a distinct relationship — aligning charging schedules with high-renewable periods can simultaneously reduce costs and improve sustainability metrics.</p>'
html += '''</div>
</div>

<!-- ═══════════════════════════════════════════════════════════════════ -->
<!-- SECTION 5: Vehicle Charging Behavior -->
<!-- ═══════════════════════════════════════════════════════════════════ -->
<div class="section" id="sec-vehicle">
<h2>5. Vehicle Charging Behavior &amp; Session Profiles</h2>
<p class="objective">Profiling charging sessions by vehicle type, examining battery capacity, initial/final SOC, energy consumed, charging duration, and priority distribution to understand fleet composition and usage patterns.</p>

<div class="chart-row">
    {chart_container('chart-vehicle-sessions')}
    {chart_container('chart-vehicle-energy')}
</div>

<h3>Vehicle Type Session Profiles</h3>
<table class="data-table">
<tr><th>Vehicle Type</th><th>Sessions</th><th>Avg Battery (kWh)</th><th>Avg Init SOC</th><th>Avg Final SOC</th><th>Avg Energy (kWh)</th><th>Avg Duration (min)</th><th>Avg Wait (min)</th></tr>'''

for vt, r in sec5_vehicle.iterrows():
    html += f'<tr><td><strong>{vt}</strong></td><td>{fmt(r["sessions"], 0)}</td><td>{fmt(r["avg_battery"])}</td><td>{pct(r["avg_init_soc"]/100)}</td><td>{pct(r["avg_final_soc"]/100)}</td><td>{fmt(r["avg_energy"])}</td><td>{fmt(r["avg_duration"])}</td><td>{fmt(r["avg_wait"])}</td></tr>'

html += '''</table>

<h3>Charging Priority Distribution</h3>
'''
if 'Low' in sec5_priority.index and 'Medium' in sec5_priority.index and 'High' in sec5_priority.index:
    html += f'<p>Low: <strong>{fmt(sec5_priority["Low"], 0)}</strong> sessions ({pct(sec5_priority["Low"]/sec5_priority.sum())}) &nbsp;|&nbsp; Medium: <strong>{fmt(sec5_priority["Medium"], 0)}</strong> sessions ({pct(sec5_priority["Medium"]/sec5_priority.sum())}) &nbsp;|&nbsp; High: <strong>{fmt(sec5_priority["High"], 0)}</strong> sessions ({pct(sec5_priority["High"]/sec5_priority.sum())})</p>'

html += f'''
<div class="insight-box">
    <h4>Fleet Composition Insight</h4>
    <p>The vehicle mix spans <strong>{len(sec5_vehicle)} types</strong>. Average initial SOC across all vehicles is <strong>{pct(df["initial_soc"].mean()/100)}</strong> with average final SOC of <strong>{pct(df["final_soc"].mean()/100)}</strong>, indicating a typical charge depth of <strong>{fmt(df["energy_consumed_kWh"].mean())} kWh</strong> per session. Larger battery vehicles (Buses, Trucks) consume more energy per session and require longer charger occupancy, making them the primary drivers of queue formation at high-traffic stations.</p>
</div>
</div>

<!-- ═══════════════════════════════════════════════════════════════════ -->
<!-- SECTION 6: Optimization Recommendations -->
<!-- ═══════════════════════════════════════════════════════════════════ -->
<div class="section" id="sec-recommendations">
<h2>6. Optimization Insights &amp; Recommendations</h2>
<p class="objective">Synthesizing findings into actionable recommendations for load balancing, queue management, pricing strategy adjustments, and renewable energy maximization.</p>

<h3>Optimization Reward by Segment</h3>
<div class="chart-row">
    {chart_container('chart-reward-slot')}
    {chart_container('chart-reward-loc')}
</div>

<table class="data-table">
<tr><th>Segment</th><th>Mean Optimization Reward</th></tr>'''

for slot in sec6_reward_by_slot.index:
    html += f'<tr><td>Time Slot: <strong>{slot}</strong></td><td>{fmt(sec6_reward_by_slot[slot], 2)}</td></tr>'
for loc in sec6_reward_by_loc.index:
    html += f'<tr><td>Location: <strong>{loc}</strong></td><td>{fmt(sec6_reward_by_loc[loc], 2)}</td></tr>'
for pri in ['Low', 'Medium', 'High']:
    if pri in sec6_reward_by_priority.index:
        html += f'<tr><td>Priority: <strong>{pri}</strong></td><td>{fmt(sec6_reward_by_priority[pri], 2)}</td></tr>'

html += '''</table>

<h3>Peak vs Off-Peak Performance Comparison</h3>
<table class="data-table">
<tr><th>Metric</th><th>Peak</th><th>Off-Peak</th><th>Delta</th></tr>'''

peak_metrics_dict = peak_metrics.to_dict()
off_peak_metrics_dict = off_peak_metrics.to_dict()

metric_labels = {
    'avg_reward': ('Avg Reward', ''),
    'avg_price': ('Avg Price', '$'),
    'avg_renew': ('Renewable Ratio', '%'),
    'avg_wait': ('Avg Wait', ' min'),
    'avg_load': ('Avg Station Load', ' kW')
}

for key, (label, unit) in metric_labels.items():
    p_val = peak_metrics_dict[key]
    o_val = off_peak_metrics_dict[key]
    if unit == '%':
        p_str = pct(p_val)
        o_str = pct(o_val)
        delta = pct(p_val - o_val)
    elif unit == '$':
        p_str = f'${fmt(p_val, 2)}'
        o_str = f'${fmt(o_val, 2)}'
        delta = f'${fmt(p_val - o_val, 2)}'
    else:
        p_str = f'{fmt(p_val)}{unit}'
        o_str = f'{fmt(o_val)}{unit}'
        delta = f'{fmt(p_val - o_val, 2)}{unit}'
    html += f'<tr><td>{label}</td><td>{p_str}</td><td>{o_str}</td><td><strong>{delta}</strong></td></tr>'

html += f'''
</table>

