# ── Pre-build chart data for JS ──────────────────────────────────────────
# Heatmap wait data: {loc: {slot: value}}
hmap_wait_data = {}
for loc in heatmap_wait.columns:
    hmap_wait_data[loc] = {}
    for slot in heatmap_wait.index:
