# Helper: sanitize numeric lists for JSON (NaN -> null)
import math

class SafeEncoder(json.JSONEncoder):
    def default(self, obj):
        return super().default(obj)
    def encode(self, o):
        return super().encode(self._sanitize(o))
    def _sanitize(self, o):
        if isinstance(o, float) and (math.isnan(o) or math.isinf(o)):
            return None
        if isinstance(o, dict):
            return {k: self._sanitize(v) for k, v in o.items()}
        if isinstance(o, (list, tuple)):
            return [self._sanitize(v) for v in o]
        if isinstance(o, np.integer):
            return int(o)
        if isinstance(o, np.floating):
            f = float(o)
            return None if (math.isnan(f) or math.isinf(f)) else f
        if isinstance(o, np.ndarray):
            return [self._sanitize(v) for v in o.tolist()]
        return o

def js_dumps(obj):
    """JSON dumps with NaN/Inf sanitization."""
    return json.dumps(obj, cls=SafeEncoder)

