# Helper: clean NaN/Inf and numpy types for JSON serialization
import math

def clean_for_json(obj):
    """Recursively replace NaN/Inf with None, numpy types with native Python."""
    if isinstance(obj, float):
        if math.isnan(obj) or math.isinf(obj):
            return None
        return obj
    if isinstance(obj, (np.floating,)):
        f = float(obj)
        return None if (math.isnan(f) or math.isinf(f)) else f
    if isinstance(obj, (np.integer,)):
        return int(obj)
    if isinstance(obj, (np.ndarray,)):
        return [clean_for_json(v) for v in obj.tolist()]
    if isinstance(obj, dict):
        return {k: clean_for_json(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple)):
        return [clean_for_json(v) for v in obj]
    return obj

def _custom_json_default(obj):
    if isinstance(obj, (np.integer,)):
        return int(obj)
    if isinstance(obj, (np.floating,)):
        f = float(obj)
        return None if (math.isnan(f) or math.isinf(f)) else f
    if isinstance(obj, (np.ndarray,)):
        return obj.tolist()
    raise TypeError(f"Object of type {type(obj)} is not JSON serializable")

def js_dumps(obj):
    """Safe JSON dumps: cleans NaN/Inf and handles numpy types."""
    cleaned = clean_for_json(obj)
    return json.dumps(cleaned, default=_custom_json_default)

